comms.text:
@1 וּמַלִיל משֶׁה עִם רֵישֵׁי שִׁבְטַּיָא לִבְנֵי יִשְׂרָאֵל לְמֵימָר דֵין פִּתְגָמָא דִי פַקֵיד יְיָ:
@2 גְבַר אֲרֵי יִדַר נְדַר קֳדָם יְיָ אוֹ יְקַיֵים קְיַם לְמֵיסַר אִסַר עַל נַפְשֵׁיהּ לָא יְבַטֵל פִּתְגָמֵיהּ כְּכָל דִי יִפּוֹק מִפּוּמֵיה יַעֲבֵּד:
@3 וְאִתְּתָא אֲרֵי תִדַר נְדַר קֳדָם יְיָ וְתֵיסַר אִסָר בְּבֵית אֲבוּהָא בְּרַבְיוּתָהָא:
@4 וְיִשְׁמַע אֲבוּהָא יָת נִדְרָהּ וְאֵסָרָהּ דִי אֲסָרַת עַל נַפְשָׁהּ וְיִשְׁתּוֹק לָהּ אֲבוּהָא וִיקוּמוּן כָּל נִדְרָהָא וְכָל אֱסָרֵי דִי אֲסָרַת עַל נַפְשָׁהּ יְקוּמוּן:
@5 וְאִם אַעְדֵי אָבוּהָא יָתַהּ בְּיוֹמָא דִשְׁמַע כָּל נִדְרָהָא וֶאֱסָרָהָא דִי אֲסָרַת עַל נַפְשָׁהּ לָא יְקוּמוּן וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לָהּ אֲרֵי אַעְדִי אֲבוּהָא יָתַהּ:
@6 וְאִם מֶהֱוָה תֶהֱוֵי לִגְבַר וְנִדְרָהָא עֲלָהּ אוֹ פֵּירוּשׁ סִפְוָתָהָא דִי אֲסָרַת עַל נַפְשָׁהּ:
@7 וְיִשְׁמַע בַּעֲלַהּ בְּיוֹמָא דִשְׁמַע וְיִשְׁתּוֹק לַהּ וִיקוּמוּן נִדְרָהָא וֶאֱסָרָהָא דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּמוּן:
@8 וְאִם בְּיוֹמָא דִשְׁמַע בַּעֲלַהּ אַעְדִי יָתַהּ וִיבַטֵּל יָת נִדְרָהָא דִי עֲלַהּ וְיָת פֵּירוּשׁ סִפְוָתָהָא דִי אֲסָרַת עַל נַפְשַׁהּ וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לַהּ:
@9 וּנְדַר אַרְמְלָא וּמְתַרְכָא כֹּל דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּם עֲלַהּ:
@10 וְאִם בֵּית בַּעֲלַהּ נְדָרַת אוֹ אֲסָרַת אִסַר עַל נַפְשַׁהּ בְּקִיוּם:
@11 וְיִשְׁמַע בַּעֲלַהּ וְיִשְׁתּוֹק לַהּ לָא אַעֲדֵי יָתַהּ וִיקוּמוּן כָּל נִדְרָהָא וְכָל אֱםָרֵי דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּמוּן:
@12 וְאִם בַּטָלָא יְבַטֵל יָתְהוֹן בַּעֲלַהּ בְּיוֹמָא דִשְׁמַע כָּל אַפָּקוּת סִפְוָתָהָא לְנִדְרָהָא וּלְאִסַר נַפְשַׁהּ לָא יְקוּמוּן בַּעֲלַהּ בְּטֵלִינוּן וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לַהּ:
@13 כָּל נְדַר וְכָל קִיוּמַת אִסַר לְסַגָפָא נְפָשׁ בַּעֲלַהּ יְקַיְמִינוּן וּבַעֲלַהּ יְבַטְלִינוּן:
@14 וְאִם מִשְׁתַּק יִשְׁתּוֹק לַהּ בַּעֲלַהּ מִיוֹם לְיוֹם וִיקַיֵים יָת כָּל נִדְרָהָא אוֹ יָת כָּל אֱסָרָהָא דִי עֲלָהּ קַיֵים יָתְהוֹן אֲרֵי שָׁתֵק לַהּ בְּיוֹמָא דִשְׁמָע:
@15 וְעִם בַּטָלָא יְבַטֵּל יָתְהוֹן בָּתַר דִשְׁמָע וִיקַבַּל יָת חוֹבַהּ:
@16 אִלֵין קְיָמַיָא דִי פַקֵיד יְיָ יָת משֶׁה בֵּין גְבַר לְאִתְּתֵיהּ בֵּין אַבָּא לִבְרַתֵּיהּ בְּרַבְיוּתָהָא בֵּית אָבוּהָא:
@17 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@18 אִתְפְּרַע פֻּרְעֲנוּת בְּנֵי יִשְׂרָאֵל מִן מִדְיָנָאֵי בָּתַר כֵּן תִּתְכְּנֵישׁ לְעַמָּךְ:
@19 וּמַלֵיל משֶׁה עִם עַמָא לְמֵימָר זְרִיזוּ מִנְכוֹן גֻבְרִין לְחֵילָא וִיהוֹן עַל מִדְיָן לְמִתַּן פּוּרְעֲנוּת דִין עַמָא דַיְיָ בְּמִדְיָן:
@20 אַלְפָא לְשִׁבְטָא אַלְפָא לְשִׁבְטָּא לְכֹל שִׁבְטַיָא דְיִשְֹׁרָאֵל תְּשַׁלְחוּן לְחֵילָא:
@21 וְאִתְבְּחָרוּ מֵאַלְפַיָא דְיִֹשְׂרָאֵל אַלְפָא לְשִׁבְטָא תְּרֵי עֲֹשַׂר אַלְפִין מְזָרְזֵי חֵילָא:
@22 וּשְׁלַח יָתְהוֹן משֶׁה אַלְפָא לְשִׁבְטָא לְחֵילָא יָתְהוֹן וְיָת פִּינְחָס בַּר אֶלְעָזָר כַּהֲנָא לְחֵילָא וּמָנֵי דְקוּדְשָׁא וַחֲצוֹצְרוֹת יַבֶּבְתָּא בִּידֵיהּ:
@23 וְאִתְחַיָילוּ עַל מִדְיָן כְּמָא דְפַקֵיד יְיָ יָת משֶׁה וּקְטָלוּ כָּל דְכוּרָא:
@24 וְיָת מַלְכֵי מִדְיָן קְטָלוּ עַל קְטִילֵיהוֹן יָת אֱוִי וְיָת רֶקֶם וְיָת צוּר וְיָת חוּר וְיָת רֶבַע חַמְשָׁא מַלְכֵי מִדְיָן וְיָת בִּלְעָם בַּר בְּעוֹר קְטָלוּ בְּחַרְבָּא:
@25 וּשְׁבוֹ בְנֵי יִשְׂרָאֵל יָת נְשֵׁי מִדְיָן וְיָת טַּפְלְהוֹן וְיָת כָּל בְּעִירְהוֹן וְיָת כָּל גֵיתֵיהוֹן וְיָת כָּל נִכְסֵיהוֹן בְּזוֹ:
@26 וְיָת כָּל קִרְוֵיהוֹן בְּמוֹתְבָנֵיהוֹן וְיָת כָּל בֵּית סִגְדַתְהוֹן אוֹקִידוּ בְּנוּרָא:
@27 וּנְסִיבוּ יָת כָּל עֲדָאָה וְיָת כָּל דְבַרְתָּא בֶּאֱנָשָׁא וּבִבְעִירָא:
@28 וְאַיתִיוּ לְוָת משֶׁה וּלְוָת אֶלְעָזָר כַּהֲנָא וּלְוָת כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל יָת שִׁבְיָא וְיָת דְבַרְתָּא וְיָת עֲדָאָה לְמַשְׁרִיתָא לְמֵישְׁרַיָא דְמוֹאָב דִי עַל יַרְדְנָא דִירֵחוֹ:
@29 וּנְפָקוּ משֶׁה וְאֶלְעָזָר כַּהֲנָא וְכָל רַבְרְבֵי כְנִשְׁתָּא לְקֳדָמוּתְהוֹן לְמִבָּרָא לְמַשְׁרִיתָא:
@30 וּרְגֵיז משֶׁה עַל דִמְמַנָן עַל חֵילָא רַבָּנֵי אַלְפִין וְרַבָּנֵי מַאֲוָותָא דְאָתוּ מֵחֵיל קְרָבָא:
@31 וַאֲמַר לְהוֹן משֶׁה הֲקַיֵמְתּוּן כָּל נוּקְבָא:
@32 הָא אִינוּן הֲוָאָה לִבְנֵי יִשְׂרָאֵל בַּעֲצַת בִּלְעָם לְשַׁקָרָא שְׁקָר קֳדָם יְיָ עַל עֵסַק פְּעוֹר וַהֲוַת מוֹתָנָא בִּכְנִשְׁתָּא דַיְיָ:
@33 וּכְעַן קְטוּלוּ כָּל דְכוּרָא בְּטַפְלָא וְכָל אִתְּתָא דִידַעַת גְבַר לְמִשְׁכַּב דְכוּרָא קְטּוּלוּ:
@34 וְכָל טַפְלָא בִנְשַׁיָא דִי לָא יְדָעוּ מִשְׁכַּב דְכוּרָא קַיְימוּ לְכוֹן:
@35 וְאַתּוּן שְׁרוֹ מִבָּרָא לְמַשְׁרִיתָא שַׁבְעָא יוֹמִין כָּל דִי קְטַל נַפְשָׁא וְכֹל דִי קְרַב בְּקָטִילָא תַּדוּן עֲלוֹהִי בְּיוֹמָא תְלִיתָאָה וּבְיוֹמָא שְׁבִיעָאָה אַתּוּן וּשְׁבִיכוֹן:
@36 וְכָל לְבוּשׁ וְכָל מַאן דִמְשַׁךְ וְכָל עוֹבַד מֵעַזֵי וְכָל מַאן דְעָא תַּדוּן עֲלוֹהִי:
@37 וַאֲמַר אֶלְעָזָר כַּהֲנָא לְגַבְרֵי חֵילָא דַאֲתוֹ לִקְרָבָא דָא גְזֵירַת אוֹרַיְיתָא דִי פַקֵיד יְיָ יָת משֶׁה:
@38 בְּרַם יָת דַהֲבָא וְיָת כַסְפָּא יָת נְחָשָׁא יָת פַּרְזְלָא יָת אֲבָצָא וְיָת אֲבָרָא:
@39 כָּל מִדַעַם דְמִתָּעַל בְּנוּרָא תַּעֲבְרוּנֵיהּ בְּנוּרָא וְיִדְכֵּי בְּרַם בְּמֵי אַדָיוּתָא יִתָּדֵי וְכָל דִי לָא מִתָּעַל בְּנוּרָא תַּעַבְרוּנֵיהּ בְּמַיָא:
@40 וּתְחַוְרוּן לְבוּשֵׁיכוֹן בְּיוֹמָא שְׁבִיעָאָה וְתִדְכּוּן וּבָתַר כֵּן תַּעֲלוּן לְמַשְׁרִיתָא:
@41 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@42 קַבֵּל יָת חוּשְׁבַּן דַבְרַת שִׁבְיָא בֶּאֱנָשָׁא וּבִבְעִירָא אַתְּ וְאֶלְעָזָר כַּהֲנָא וְרֵישֵׁי אֲבָהַת כְּנִשְׁתָּא:
@43 וּתְפַלֵג יָת דְבַרְתָּא בֵּין גַבְרֵי מַגִיחֵי קְרָבָא דְנְפָקוּ לְחֵילָא וּבֵין כָּל כְּנִשְׁתָּא:
@44 וְתַפְרֵשׁ נְסִיבָא קֳדָם יְיָ מִן גַבְרֵי מְגִיחֵי קְרָבָא דִנְפָקוּ לְחֵילָא חָד נַפְשָׁא מֵחֲמֵשׁ מְאָה מִן אֱנָשָׁא וּמִן תּוֹרֵי וּמִן חֲמָרֵי וּמִן עָנָא:
@45 מִפַּלְגוּתְהוֹן תִּסְבוּן וְתִתֵּן לְאֶלְעָזָר כַּהֲנָא אַפְרָשׁוּתָא קֳדָם יְיָ:
@46 וּמִפַּלְגוּת בְּנֵי יִשְׂרָאֵל תִּסַב חָד דְאִתַּחָד מִן חַמְשִׁין מִן אֱנָשָׁא מִן תּוֹרֵי מִן חֲמָרֵי וּמִן עָנָא מִכָּל בְּעִירָא וְתִתֵּן יָתְהוֹן לְלֵוָאֵי נַטְרֵי מַטְרַת מַשְׁכְּנָא דַיְיָ:
@47 וַעֲבַד משֶׁה וְאֶלְעָזָר כַּהֲנָא כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@48 וַהֲוָה דְבַרְתָּא שְׁאָר בִּיזָא דִי בְזוֹ עַמָא דִי נְפָקוּ לְחֵילָא עָנָא שִׁית מְאָה וְשַׁבְעִין וְחַמְשָׁא אַלְפִין:
@49 וְתוֹרֵי שַׁבְעִין וּתְרֵין אַלְפִין:
@50 וַחֲמָרֵי שִׁיתִּין וְחָד אַלְפִין:
@51 וְנַפְשָׁא דֶאֱנָשָׁא מִן נְשַׁיָא דִי לָא יְדָעָא מִשְׁכְּבֵי דְכוּרָא כָּל נַפְשָׁתָא תְּלָתִין וּתְרֵין אַלְפִין:
@52 וַהֲוַת פַלְגוּתָא חוּלַק גוּבְרַיָא דִנְפָקוּ לְחֵילָא מִנְיַן עָנָא תְּלַת מְאָה וּתְלָתִין וּשְׁבַע אַלְפִין וַחֲמֵשׁ מְאָה:
@53 וַהֲוָה נְסִיבָא קֳדָם יְיָ מִן עָנָא שִׁית מְאָה שַׁבְעִין וַחֲמֵשׁ:
@54 וְתוֹרֵי תְּלָתִין וְשִׁתָּא אַלְפִין וּנְסֵיבְהוֹן קֳדָם יְיָ שַׁבְעִין וּתְרֵין:
@55 וַחֲמָרֵי תְּלָתִין אַלְפִין וַחֲמֵשׁ מְאָה וּנְסֵיבְהוֹן קֳדָם יְיָ שִׁתִּין וְחָד:
@56 וְנַפְשָׁא אֱנָשָׁא שִׁתָּא עֲשַׂר אַלְפִין וּנְסֵבְהוֹן קֳדָם יְיָ תְּלָתִין וּתְרֵין נַפְשִׁין:
@57 וִיהַב משֶׁה יָת נְסִיב אַפְרָשׁוּתָא קֳדָם יְיָ לְאֶלְעָזָר כַּהֲנָא כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@58 וּמִפַּלְגוּת בְּנֵי יִשְׂרָאֵל דִי פְּלַג משֶׁה מִן גוּבְרַיָא דִנְפָקוּ לְחֵילָא:
@59 וַהֲוַת פַּלְגוּת כְּנִשְׁתָּא מִן עָנָא תְּלַת מְאָה וּתְלָתִין וְשַׁבְעָא אַלְפִין וַחֲמֵשׁ מְאָה:
@60 וְתוֹרֵי תְּלָתִין וְשִׁתָּא אַלְפִין וַחֲמֵשׁ מְאָה:
@61 וַחֲמָרֵי תְּלָתִין אַלְפִין וַחֲמֵשׁ מְאָה:
@62 וְנַפְשָׁא דְאֱנָשָׁא שִׁתָּא עֲשַׂר אַלְפִין:
@63 וּנְסֵב משֶׁה מִפַּלְגוּת בְּנֵי יִשְׂרָאֵל יָת דְאִתַּחָד חָד מִן חַמְשִׁין מִן אֱנָשָׁא וּמִן בְּעִירָא וִיהַב יָתְהוֹן לְלֵוָאֵי נַטְּרֵי מַטְרַת מַשְׁכְּנָא דַיְיָ כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@64 וּקְרִיבוּ לְוָת משֶׁה דִמְמַנָן עַל אַלְפֵי חֵילָא רַבָּנֵי אַלְפִין וְרַבָּנֵי מַאֲוָתָא:
@65 וַאֲמָרוּ לְמשֶׁה עַבְדָיךְ קַבִּילוּ יָת חוּשְׁבַּן גַבְרֵי מְגִיחֵי קְרָבָא דִי עִמָנָא וְלָא שְׁגָא מִנָנָא אֱנָשׁ:
@66 וְקָרֶבְנָא יָת קוּרְבָּנָא דַיְיָ גְבַר דְאַשְׁכַּח מַאן דִדְהַב שִׁירִין וְשִׁבְּכִין עִזְקָן קַדָשִׁין וּמָחוֹךְ לְכַפָּרָא עַל נַפְשָׁתָנָא קֳדָם יְיָ:
@67 וּנְסֵיב משֶׁה וְאֶלְעָזר כַּהֲנָא יָת דַהֲבָא מִנְהוֹן כָּל מַאן דְעוֹבָדָא:
@68 וַהֲוָה כָּל דְהַב אַפְרָשׁוּתָא דְאַפְרָשׁוּ קֳדָם יְיָ שִׁתָּא עַשֲׂר אַלְפִין שְׁבַע מְאָה וְחַמְשִׁין סִלְעִין מִן רַבָּנֵי אַלְפִין וּמִן רַבָּנֵי מַאֲוָתָא:
@69 גַבְרֵי דְחֵילָא בָּזוּ גְבַר לְנַפְשֵׁיהּ:
@70 וּנְסֵיב משֶׁה וְאֶלְעָזָר כַּהֲנָא יָת דַהֲבָא מִן רַבָּנֵי אַלְפִין וּמַאֲוָתָא וְאַיְתִיאוּ יָתֵיהּ לְמַשְׁכַּן זִמְנָא דָכְרָנָא לִבְנֵי יִשְׂרָאֵל קֳדָם יְיָ:
@71 וּבְעִיר סַגִי הֲוָה לִבְנֵי רְאוּבֵן וְלִבְנֵי גָד תַּקֵּיף לַחֲדָא וַחֲזוֹ יָת אֲרַע יַעְזֵר וְיָת אֲרַע גִּלְעָד וְהָא אַתְרָא אֲתַר כְּשַׁר לְבֵית בְּעִיר:
@72 וַאֲתוֹ בְנֵי גָד וּבְנֵי רְאוּבֵן וַאֲמָרוּ לְמשֶׁה וּלְאֶלְעָזָר כַּהֲנָא וּלְרַבְרְבֵי כְּנִשְׁתָּא לְמֵימָר:
@73 מַכְלֶלְתָּא וּמַלְבֶּשְׁתָּא וְכוּמְרִין וּבֵית נִמְרִין וּבֵית חוּשְׁבָּנָא וּבַעֲלֵי דְבָבָא וְסִימָא וּבֵית קְבוּרְתָּא דְמשֶׁה וּבְעוֹן:
@74 אַרְעָא דִי מְחָא יְיָ יַת יָתְבָהָא קֳדָם כְּנִשְׁתָּא דְיִשְׂרָאֵל אֲרַע כָּשְׁרָא לְבֵית בְּעִיר הִיא וּלְעַבְדָיךְ אִית בְּעִיר:
@75 וַאֲמָרוּ אִם אַשְׁכַּחְנָא רַחֲמִין בְּעֵינָיךְ תִּתְיְהִיב יָת אַרְעָא הָדָא לְעַבְדָךְ לְאַחֲסָנָא לָא תְעַבְרִינָנָא יָת יַרְדְנָא:
@76 וַאֲמַר משֶׁה לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן הַאֲחֵיכוֹן יֵיתוּן לִקְרָבָא וְאַתּוּן תֵּתְבוּן הָכָא:
@77 וּלְמָא תוֹנוּן יָת לִבָּא דִבְנֵי יִשְׂרָאֵל מִלְמֶעֱבַר לְאַרְעָא דִיהַב לְהוֹן יְיָ:
@78 כְּדֵין עֲבָדוּ אֲבָהַתְכוֹן כַּד שְׁלָחִית יָתְהוֹן מֵרְקַם גֵיאָה לְמֶחֱזֵי יָת אַרְעָא:
@79 וּסְלִיקוּ עַד נַחֲלָא דְאַתְכָּלָא וַחֲזוֹ יָת אַרְעָא וְאוֹנִיאוּ יָת לִבָּא דִבְנֵי יִשְׂרָאֵל בְּדִיל דְלָא לְמֵיעַל לְאַרְעָא דִיהַּב לְהוֹן יְיָ:
@80 וּתְקֵיף רוּגְזָא דַיְיָ בְּיוֹמָא הַהוּא וְקַיֵים לְמֵימָר:
@81 אִם יֶחֱזוּן גֻבְרַיָא דִסְלִיקוּ מִמִצְרַיִם מִבַּר עַשְׂרִין שְׁנִין וּלְעֵילָא יָת אַרְעָא דִי קַיֵימִית לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב אֲרֵי לָא אַשְׁלִימוּ בָּתַר דַחַלְתִּי:
@82 אֱלָהֵן כָּלֵב בַּר יְפֻנֶה קְנִזָאָה וִיהוֹשֻׁעַ בַּר נוּן אֲרֵי אַשְׁלִימוּ בָּתַר דַחַלְתָּא דַיְיָ:
@83 וּתְקֵיף רוּגְזָא דַיְיָ בְּיִשְׂרָאֵל וּטְרָדִנוּן בְּמַדְבְּרָא אַרְבְּעִין שְׁנִין עַד דְסַף כָּל דָרָא דְעָבִיד דְבִישׁ קֳדָם יְיָ:
@84 וְהָא קַמְתּוּן חֲלַף אֲבָהַתְכוֹן תַּלְמִידֵי גֻבְרַיָא חַיָבַיָא לְאוֹסָפָא עוֹד עַל תְּקוֹף רוּגְזָא דַיְיָ לְיִשְׂרָאֵל:
@85 אֲרֵי תְתוּבוּן מִבָּתַר דַחַלְתֵּיהּ וְיוֹסִיף עוֹד לְאַחֲרוּתְהוֹן בְּמַדְבְּרָא וּתְחַבְּלוּן לְכָל עַמָא הָדֵין:
@86 וּקְרִיבוּ לְוָתֵיהּ וַאֲמָרוּ חַטְרִין דְעָאן נִבְנֵי לִבְעִירָנָא הָכָא וְקִרְוִין לְטַפְלָנָא:
@87 וַאֲנַחְנָא נִזְדָרֵיז מַבְעִין קֳדָם בְּנֵי יִשְׂרָאֵל עַד דִי נְעֵלִינוּן לְאַתְרֵהוֹן וְיֵתְבוּן טַפְלָנָא בְּקִרְוִין כְּרִיכִין מִן קֳדָם יַתְבֵי אַרְעָא:
@88 לָא נְתוּב לְבֵיתָנָא עַד דְיַחְסְנוּן בְּנֵי יִשְׂרָאֵל גְבַר אַחֲסַנְתֵּיהּ:
@89 אֲרֵי לָא נַחֲסִין עִמְהוֹן מֵעִבְרָא לְיַרְדְנָא וּלְהָלָא אֲרֵי קַבֵּילְנָא אַחֲסַנְתָּנָא לָנָא מֵעִבְרָא לְיַרְדְנָא מַדִינְחָא:
@90 וַאֲמַר לְהוֹן משֶׁה אִם תַּעְבְדוּן יָת פִּתְגָמָא הָדֵין אִם תִּזְדָרְזוּן קֳדָם עַמָא דַיְיָ לִקְרָבָא:
@91 וְיַעְבֵר לְכוֹן כָּל דִמְזָרֵז יָת יַרְדְנָא קֳדָם עַמָא דַיְיָ עַד דִיתָרַךְ יָת בַּעֲלֵי דְבָבוֹהִי מִן קֳדָמוֹהִי:
@92 וְתִתְכְּבֵשׁ אַרְעָא קֳדָם עַמָא דַיְיָ וּבָתַר כֵּן תְּתוּבוּן וּתְהוֹן זַכָּאִין מִן קֳדָם יְיָ וּמִיִשְׂרָאֵל וּתְהֵי אַרְעָא הָדָא לְכוֹן לְאַחֲסָנָא קֳדָם יְיָ:
@93 וְאִם לָא תַעְבְדוּן כֵּן הָא חַבְתּוּן קֳדָם יְיָ וְתֵדְעוּן חוֹבַתְכוֹן דְתַשְׁכַּח יָתְכוֹן:
@94 בְּנוּ לְכוֹן קִרְוִין לְטַפְלְכוֹן וְחַטְרִין לְעַנְכוֹן וּדְיִפּוֹק מִפּוּמְכוֹן תַּעְבְּדוּן:
@95 וַאֲמָרוּ בְנֵי גָד וּבְנֵי רְאוּבֵן לְמשֶׁה לְמֵימָר עַבְדָיךְ יַעְבְדוּן כְּמָא דִי רִבּוֹנִי מְפַקֵד:
@96 טַפְלָנָא נְשָׁנָא גֵיתָנָא וְכָל בְּעִירָנָא יְהוֹן תַּמָן בְּקִרְוֵי גִלְעָד:
@97 וְעַבְדָיךְ יַעְבְּרוּן כָּל מְזָרַז חֵילָא קֳדָם עַמָא דַיְיָ לִקְרָבָא כְּמָא דִי רִבּוֹנִי מְמַלֵל:
@98 וּפַקֵד לְהוֹן משֶׁה יָת אֶלְעָזָר כַּהֲנָא וְיָת יְהוֹשֻׁעַ בַּר נוּן וְיָת רֵישֵׁי אֲבָהַת שִׁבְטַיָא לִבְנֵי יִשְׂרָאֵל:
@99 וַאֲמַר משֶׁה לְהוֹן אִם יַעְבְּרוּן בְּנֵי גָד וּבְנֵי רְאוּבֵן עִמְכוֹן יָת יַרְדְנָא כָּל דִמְזָרַז לִקְרָבָא קֳדָם עַמָא דַיְיָ וְתִתְכְּבֵשׁ אַרְעָא קֳדָמֵיכוֹן וְתִתְּנוּן לְהוֹן יָת אַרְעָא דְגִלְעָד לְאַחֲסָנָא:
@100 וְאִם לָא יַעְבְרוּן מְזָרְזִין עִמְכוֹן וְיַחְסְנוּן בֵּינֵיכוֹן בְּאַרְעָא דִכְנָעַן:
@101 וְאָתִיבוּ בְנֵי גָד וּבְנֵי רְאוּבֵן לְמֵימָר יָת דִי מַלִיל יְיָ לְעַבְדָךְ כֵּן נַעְבֵּד:
@102 נַחְנָא נַעֲבֵר מְזָרְזִין קֳדָם עַמָא דַיְיָ לְאַרְעָא דִכְנָעַן וְעִמָנָא אֲחוּדַת אַחֲסַנְתָּנָא מֵעִבְרָא לְיַרְדְנָא:
@103 וִיהַב לְהוֹן משֶׁה לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן וּלְפַלְגוּת שִׁבְטָא דִמְנַשֶׁה בַּר יוֹסֵף יָת מַלְכְּוַת סִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה וְיָת מַלְכְּוַת עוֹג מַלְכָּא דְמַתְנָן אַרְעָא לְקִרְוָהָא בִּתְחוּמִין קִרְוֵי אַרְעָא סְחוֹר סְחוֹר:
@104 וּבְנוֹ בְנֵי גָד יָת דִיבוֹן וְיָת עֲטָּרוֹת וְיָת עֲרֹעֵר:
@105 וְיָת עַטְרוֹת שׁוֹפָן וְיָת יַעְזֵר וְרָמָתָא:
@106 וְיָת בֵּית נִמְרָה וְיָת בֵּית הָרָן קִרְוִין כְּרִיכָן וְחַטְרִין דְעָאן:
@107 וּבְנֵי רְאוּבֵן בְּנוֹ יָת חֶשְׁבּוֹן וְיָת אֶלְעָלֵא וְיָת קִרְיָתָיִם:
@108 וְיָת נְבוֹ וְיָת בַּעַל מְעוֹן מַקְפָן שְׁמָהָן וְיָת שִׂבְמָה וּקְרוֹ בִשְׁמָהָן יָת שְׁמָהַת קִרְוַיָא דִי בְנוֹ:
@109 וַאֲזָלוּ בְּנֵי מָכִיר בַּר מְנַשֶׁה לְגִלְעָד וְכִבְשׁוּהָ וְתָרִיךְ יָת אֱמוֹרָאָה דִי בָּהּ:
@110 וִיהַב משֶׁה יָת גִלְעָד לְמָכִיר בַּר מְנַשֶׁה וִיתֵב בַּהּ:
@111 וְיָאִיר בַּר מְנַשֶׁה אֲזַל וּכְבַשׁ יָת כַּפְרָנֵיהוֹן וּקְרָא יַתְהֶן כַּפְרָנֵי יָאִיר:
@112 וְנֹבַח אֲזַל וּכְבַשׁ יָת קְנַת וְיָת כַּפְרָנָהָא וּקְרָא לָה נֹבַח בִּשְׁמֵהּ: פפפ:

@1 **ראשי המטות.** חלק כבוד לנשיאים ללמדם תחלה ואחר כך לכל בני ישראל. ומנין שאף שאר הדברות כן, תלמוד לומר (שמות לד, לא. לב) וישבו אליו אהרן וכל הנשאים בעדה וידבר משה אליהם ואחרי כן נגשו כל בני ישראל. ומה ראה לאמרה כאן, למד שהפרת נדרים ביחיד ממחה ואם אין יחיד ממחה מפר בשלשה הדיוטות. או יכול שלא אמר משה פרשה זו אלא לנשיאים בלבד, נאמר כאן זה הדבר, ונאמר בשחוטי חוץ (ויקרא יז, ב) זה הדבר, מה להלן נאמרה לאהרן ולבניו ולכל בני ישראל, שנאמר דבר אל אהרן וגו' , אף זו נאמרה לכלן: **זה הדבר.** משה נתנבא (שמות יא, ד) בכה אמר ה' כחצות הלילה, והנביאים נתנבאו בכה אמר ה', מוסף עליהם משה שנתנבא בלשון זה הדבר. דבר אחר זה הדבר מעוט הוא, לומר שהחכם בלשון התרה ובעל בלשון הפרה, כלשון הכתוב כאן, ואם חלפו אין מתר ואין מופר:
@2 **נדר.** האומר הרי עלי קנם שלא אוכל או שלא אעשה דבר פלוני, יכול אפלו נשבע שיאכל נבלות אני קורא עליו ככל היוצא מפיו יעשה, תלמוד לומר לאסר אסר את המתר ולא להתיר את האסור: **לא יחל דברו.** כמו לא יחלל דברו, לא יעשה דבריו חלין:
@3 **בבית אביה.** ברשות אביה ואפלו אינה בביתו: **בנעריה.** ולא קטנה ולא בוגרת, שהקטנה אין נדרה נדר והבוגרת אינה ברשותו של אביה להפר נדריה. ואי זו היא קטנה, אמרו רבותינו בת אחת עשרה שנה ויום אחד נדריה נבדקין. אם ידעה לשם מי נדרה ולשם מי הקדישה נדרה נדר. בת שתים עשרה שנה ויום אחד אינה צריכה להבדק:
@5 **ואם הניא אביה אתה.** אם מנע אותה מן הנדר, כלומר שהפר לה. הנאה זו איני יודע מה היא, כשהוא אומר ואם ביום שמע אישה יניא אותה והפר, הוי אומר הנאה זו הפרה. ופשוטו לשון מניעה והסרה וכן (במדבר לב, ז) ולמה תניאון, וכן (תהלים קמא, ה) שמן ראש אל יני ראשי, וכן (במדבר יד, לד) וידעתם את תנואתי, את אשר סרתם מעלי: **וה' יסלח לה.** במה הכתוב מדבר באשה שנדרה בנזיר ושמע בעלה והפר לה והיא לא ידעה ועוברת על נדרה ושותה יין ומטמאה למתים, זו היא שצריכה סליחה, ואף על פי שהוא מופר. ואם המופרים צריכים סליחה, קל וחמר לשאינן מופרים:
@6 **ואם היו תהיה לאיש.** זו ארוסה או אינו אלא נשואה, כשהוא אומר ואם בית אישה נדרה, הרי נשואה אמור וכאן בארוסה, ובא לחלק בה, שאביה ובעלה מפירין נדרה. הפר האב ולא הפר הבעל או הפר הבעל ולא הפר האב, הרי זה אינו מופר, ואין צריך לומר אם קים אחד מהם: **ונדריה עליה.** שנדרה בבית אביה ולא שמע בהן אביה ולא הופרו ולא הוקמו:
@7 **ושמע אישה** וגו' **.** הרי לך שאם קים הבעל שהוא קים:
@8 **והפר את נדרה אשר עליה.** יכול אפלו לא הפר האב, תלמוד למר בנעריה בית אביה, כל שבנעוריה ברשות אביה היא:
@9 **כל אשר אסרה על נפשה יקום עליה.** לפי שאינה לא ברשות אב ולא ברשות בעל, ובאלמנה מן הנשואין הכתוב מדבר, אבל אלמנה מן האירוסין, מת הבעל נתרוקנה וחזרה לרשות האב:
@10 **ואם בית אישה נדרה.** בנשואה הכתוב מדבר:
@13 **כל נדר וכל שבעת אסר** וגו' **.** לפי שאמר שהבעל מפר, יכול כל נדרים במשמע, תלמוד לומר לענות נפש, אינו מפר אלא נדרי ענוי נפש בלבד. והם מפורשים במסכת נדרים (דף עט, א) :
@14 **מיום אל יום.** שלא תאמר מעת לעת, לכך נאמר מיום אל יום, ללמדך שאין מפר אלא עד שתחשך:
@15 **אחרי שמעו.** אחרי ששמע וקים, שאמר אפשי בו, וחזר והפר לה אפלו בו ביום: **ונשא את עונה.** הוא נכנס תחתיה. למדנו מכאן שהגורם תקלה לחברו הוא נכנס תחתיו לכל ענשין:
@18 **מאת המדינים.** ולא מאת המואבים, שהמואבים נכנסו לדבר מחמת יראה שהיו יראים מהם, שיהיו שוללים אותם, שלא נאמר אלא (דברים ב, ט) אל תתגר בם מלחמה. אבל מדינים נתעברו על ריב לא להם. דבר אחר מפני שתי פרידות טובות שיש לי להוציא מהם, רות המואביה ונעמה העמונית:
@19 **וידבר משה** וגו' **.** אף על פי ששמע שמיתתו תלויה בדבר עשה בשמחה ולא אחר: **החלצו.** כתרגומו לשון חלוצי צבא מזינים: **אנשים.** צדיקים, וכן (שמות יז, ט) בחר לנו אנשים, וכן (דברים א, טו) אנשים חכמים וידעים: **נקמת ה'.** שהעומד כנגד ישראל, כאלו עומד כנגד הקדוש ברוך הוא:
@20 **לכל מטות ישראל.** לרבות שבט לוי:
@21 **וימסרו.** להודיעך שבחן של רועי ישראל כמה הם חביבים על ישראל, עד שלא שמעו במיתתו מה הוא אומר (שמות יז, ד) עוד מעט וסקלני, ומששמעו שמיתת משה תלויה בנקמת מדין, לא רצו ללכת עד שנמסרו על כרחן:
@22 **אתם ואת פנחס.** מגיד שהיה פנחס שקול כנגד כלם. ומפני מה הלך פנחס ולא הלך אלעזר. אמר הקדוש ברוך הוא מי שהתחיל במצוה, שהרג כזבי בת צור, יגמור. דבר אחר שהלך לנקום נקמת יוסף אבי אמו, שנאמר (בראשית לז, לו) והמדנים מכרו אתו. ומנין שהיתה אמו של פנחס משל יוסף, שנאמר (שמות ו, כה) מבנות פוטיאל, מזרע יתרו שפטם עגלים לעבודה זרה ומזרע יוסף שפטפט ביצרו. דבר אחר שהיה משוח מלחמה: **וכלי הקדש.** זה הארון והציץ. שהיה בלעם עמהם ומפריח מלכי מדין בכשפים, והוא עצמו פורח עמהם. הראה להם את הציץ, שהשם חקוק בו, והם נופלים, לכך נאמר על חלליהם במלכי מדין, שנופלים על החללים מן האויר, וכן בבלעם כתיב (יהושע יג, כב) אל חלליהם: **בידו.** ברשותו וכן (במדבר כא, כז) ויקח את כל ארצו מידו:
@24 **חמשת מלכי מדין.** וכי איני רואה שחמשה מנה הכתוב, למה הזקק לומר חמשת, אלא ללמדך ששוו כלם בעצה והשוו כלם בפרענות. בלעם הלך שם לטול שכר עשרים וארבעה אלף שהפיל מישראל בעצתו, ויצא ממדין לקראת ישראל ומשיאן עצה רעה. אמר להם אם כשהייתם ששים רבוא לא יכלתם להם, ועכשיו בשנים עשר אלף אתם באים להלחם. נתנו לו שכרו משלם ולא קפחוהו: **בחרב.** הוא בא על ישראל, והחליף אמנותו באמנותם, שאין נושעים אלא בפיהם על ידי תפלה ובקשה. ובא הוא ותפש אמנותם לקללם בפיו, אף הם באו עליו והחליפו אמנותם באמנות האמות, שבאין בחרב, שנאמר (בראשית כז, מ) ועל חרבך תחיה:
@26 **טירתם.** מקום פלטרין שלהם, שהוא לשון מושב כומרים יודעי חקיהם. דבר אחר לשון מושב שריהם, כמו שמתרגם סרני פלשתים טורני פלשתאי:
@27 **ויקחו את כל השלל** וגו' **.** מגיד שהיו כשרים וצדיקים ולא נחשדו על הגזל לשלוח יד בבזה שלא ברשות, שנאמר את כל השלל וגו' , ועליהם מפורש בקבלה שניך כעדר הרחלים וגו' , אף אנשי המלחמה שביך כלם צדיקים: **שלל.** הן מטלטלין של מלבוש ותכשיטין: **בז.** הוא בזת מטלטלין שאינם תכשיטין: **מלקוח.** אדם ובהמה. ובמקום שכתוב שבי אצל מלקוח, שבי באדם ומלקוח בבהמה:
@29 **ויצאו משה ואלעזר הכהן.** לפי שראו את נערי ישראל יוצאים לחטף מן הבזה:
@30 **ויקצף משה על פקודי החיל.** ממנים על החיל, ללמדך שכל סרחון הדור תלוי בגדולים שיש כח בידם למחות:
@32 **הן הנה.** מגיד שהיו מכירין אותן. זו היא שנכשל פלוני בה: **בדבר בלעם.** אמר להם אפלו אתם מכניסים כל המונות [האמות] שבעולם אין אתם יכולים להם, שמא מרבים אתם מן המצרים שהיו שש מאות רכב בחור. בואו ואשיאכם עצה. אלהיהם של אלו שונא זמה הוא וכו' , כדאיתא בחלק (סנהדרין קו.) ובספרי:
@33 **וכל אשה ידעת איש.** ראויה להבעל אף על פי שלא נבעלה. ולפני הציץ העבירום והראויה להבעל פניה מוריקות: **הרגו.** למה חזר ואמר, להפסיק הענין, דברי ר' ישמעאל, שאם אני קורא הרגו כל זכר בטף וכל אשה ידעת איש וכל הטף בנשים וגו' איני יודע אם להרוג עם הזכרים או להחיות עם הטף, לכך נאמר הרגו:
@35 **מחוץ למחנה.** שלא יכנסו לעזרה: **כל הרג נפש.** ר' מאיר אומר בהורג בדבר המקבל טמאה הכתוב מדבר, ולמדך הכתוב שהכלי מטמא אדם בחבורי המת, כאלו נוגע במת עצמו, או יכול אפלו זרק בו חץ והרגו, תלמוד לומר וכל נגע בחלל, מקיש הורג לנוגע, מה נוגע על ידי חבורו, אף הורג על ידי חבורו: **תתחטאו.** במי נדה, כדין שאר טמאי מתים, שאף לדברי האומרים קברי גוים אינן מטמאין באהל, שנאמר (יחזקאל לד, לא) ואתן צאני צאן מרעיתי אדם אתם, אתם קרויין אדם ואין הגוים קרויין אדם, מודה הוא שהגוים מטמאין במגע ובמשא, שלא נאמר אדם אלא אצל טמאת אהלים, שנאמר אדם כי ימות באהל: (במדבר יט, יד) **אתם ושביכם.** לא שהנכרים מקבלין טמאה וצריכין הזאה, אלא מה אתם בני ברית, אף שביכם כשיבואו לברית ויטמאו, צריכין הזאה:
@36 **וכל מעשה עזים.** להביא כלי הקרנים והטלפים והעצמות:
@37 **ויאמר אלעזר הכהן** וגו' **.** לפי שבא משה לכלל כעס בא לכלל טעות, שנתעלמו ממנו הלכות גיעולי נכרים. וכן אתה מוצא בשמיני למלואים, שנאמר (ויקרא י, טז) ויקצף על אלעזר ועל איתמר, בא לכלל כעס, בא לכלל טעות, וכן (במדבר כ, י. יא) בשמעו נא המרים ויך את הסלע, על ידי הכעס טעה: **אשר צוה ה'** וגו' **.** תלה ההוראה ברבו:
@38 **אך את הזהב** וגו' **.** אף על פי שלא הזהיר לכם משה אלא על הלכות טמאה, עוד יש להזהיר לכם על הלכות געול. ואך לשון מעוט, כלומר ממועטין אתם מלהשתמש בכלים אפלו לאחר טהרתן מטמאת המת, עד שיטהרו מבליעת אסור נבלות. ורבותינו אמרו אך את הזהב לומר שצריך להעביר חלודה שלו קודם שיגעילנו, וזהו לשון אך, שלא יהא שם חלודה, אך המתכת יהיה כמות שהוא:
@39 **כל דבר אשר יבא באש.** לבשל בו כלום: **תעבירו באש.** כדרך תשמישו הגעלתו, מה שתשמישו על ידי חמין, יגעילנו בחמין, ומה שתשמישו על ידי צלי, כגון השפוד והאסכלה, ילבננו באור: **אך במי נדה יתחטא.** לפי פשוטו חטוי זה לטהרו מטמאת מת. אמר להם צריכין הכלים געול לטהרם מן האסור, וחטוי לטהרן מן הטמאה. ורבותינו דרשו מכאן, שאף להכשירן מן האסור הטעין טבילה לכלי מתכות. ומי נדה הכתובין כאן דרשו מים הראוים לטבול בהם נדה. וכמה הם, ארבעים סאה: **וכל אשר לא יבא באש.** כל דבר שאין תשמישו על ידי האור, כגון כוסות וצלוחיות שתשמישן בצונן ולא בלעו אסור: **תעבירו במים.** מטבילן ודיו ודוקא כלי מתכות:
@40 **אל המחנה.** למחנה שכינה, שאין טמא מת טעון שלוח ממחנה לויה וממחנה ישראל:
@42 **שא את ראש.** קח את החשבון:
@43 **וחצית את המלקוח בין תפשי המלחמה** וגו' **.** חציו לאלו וחציו לאלו:
@48 **ויהי המלקוח יתר הבז.** לפי שלא נצטוו להרים מכס מן המטלטלין אלא מן המלקוח, כתב את הלשון הזה, ויהי המלקוח שבא לכלל חלקה ולכלל מכס, שהיה עודף על בז המטלטלין אשר בזזו עם הצבא איש לו, ולא בא לכלל חלקה מספר הצאן וגו' :
@58 **וממחצית בני ישראל אשר חצה משה.** לעדה והוציאה להם מן האנשים הצובאים:
@59 **ותהי מחצת העדה.** כך וכך:
@64 **ויקח משה** וגו' **הפקדים.** הממנים:
@65 **ולא נפקד.** ולא נחסר ותרגומו ולא שגא, אף הוא בלשון ארמי חסרון, כמו אנכי אחטנה, (בראשית לא, לט) תרגומו דהות שגיא ממנינא, וכן כי יפקד מושבך (שמואל א' כ, יח) , יחסר מקום מושבך, איש הרגיל לישב שם. וכן (שם כ, כז) ויפקד מקום דוד, נחסר מקומו ואין איש יושב שם:
@66 **אצעדה.** אלו צמידים של רגל: **וצמיד.** של יד: **עגיל.** נזמי אזן: **וכומז.** דפוס של בית הרחם לכפר על הרהור הלב של בנות מדין:
@73 **עטרות ודיבון** וגו' **.** מארץ סיחון ועוג היו:
@76 **האחיכם.** לשון תמיהה הוא:
@77 **ולמה תניאון.** תסירו ותמניעו לבם מעבור שיהיו סבורים שאתם יראים לעבור מפני המלחמה וחוזק הערים והעם:
@78 **מקדש ברנע.** כך שמה, ושני קדש היו:
@82 **הקנזי.** חורגו של קנז היה, וילדה לו אמו של כלב את עתניאל:
@83 **וינעם.** ויטלטלם. מן נע ונד:
@84 **לספות.** כמו (ישעיה כט, א) ספו שנה על שנה, (ירמיה ז, כא) עולותיכם ספו וגו' , לשון תוספת:
@86 **נבנה למקננו פה.** חסים היו על ממונם יותר מבניהם ובנותיהם, שהקדימו מקניהם לטפם. אמר להם משה לא כן עשו, העיקר עיקר והטפל טפל, בנו לכם תחלה ערים לטפכם ואחר כך גדרות לצאנכם:
@87 **ואנחנו נחלץ חשים.** נזדרז מהירים, כמו (ישעיה ח, א) מהר שלל חש בז, (ישעיה ה, יט) ימהר יחישה: **לפני בני ישראל.** בראשי גיסות, מתוך שגבורים היו, שכן נאמר בגד (דברים לג, כ) וטרף זרוע אף קדקד, ואף משה חזר ופרש להם באלה הדברים (דברים ג, יח) ואצו אתכם בעת ההיא וגו' חלוצים תעברו לפני אחיכם בני ישראל כל בני חיל. וביריחו כתיב (יהושע ו, יג) והחלוץ הולך לפניהם, זה ראובן וגד שקימו תנאם: **וישב טפנו.** בעודנו אצל אחינו: **בערי המבצר.** שנבנה עכשיו:
@89 **מעבר לירדן** וגו' **.** בעבר המערבי: **כי באה נחלתנו.** כבר קבלנוה בעבר המזרחי:
@94 **לצנאכם.** תיבה זו מגזרת (תהלים ח, ח) צנה ואלפים כלם, שאין בו אל''ף מפסיק בין נו''ן לצד''י, ואל''ף שבא כאן אחר הנו''ן במקום ה''א של צנה הוא. מיסודו של ר' משה הדרשן למדתי כן: **והיצא מפיכם תעשו.** לגבוה שקבלתם עליכם לעבור למלחמה עד כבוש וחלוק. שמשה לא בקש מהם אלא ונכבשה ואחר תשבו, והם קבלו עליהם עד התנחל, הרי הוסיפו להתעכב שבע שחלקו, וכן עשו:
@95 **ויאמר בני גד.** כלם כאיש אחד:
@98 **ויצו להם.** כמו עליהם, ועל תנאם מנה אלעזר ויהושע, כמו (שמות יד, יד) ה' ילחם לכם:
@102 **ואתנו אחזת נחלתנו.** כלומר בידינו וברשותנו תהי אחזת נחלתנו מעבר הזה:
@106 **ערי מבצר וגדרות צאן.** זה סוף הפסוק מוסב על תחלת הענין, ויבנו בני גד את הערים הללו להיות ערי מבצר וגדרות צאן:
@108 **ואת נבו ואת בעל מעון מוסבת שם.** נבו ובעל מעון שמות עבודה זרה הם, והיו האמוריים קורים עריהם על שם עבודה זרה שלהם, ובני ראובן הסבו את שמם לשמות אחרים, וזהו מסבות שם, נבו ובעל מעון מוסבות לשם אחר: **ואת שבמה.** בנו שבמה והיא שבם האמורה למעלה:
@109 **ויורש.** כתרגומו ותריך. שתבת רי''ש משמשת שתי חלקות לשון ירשה ולשון הורשה, שהוא טירוד ותירוך:
@111 **חותיהם.** כפרניהון: **ויקרא אתהן חות יאיר.** לפי שלא היו לו בנים קראם בשמו לזכרון:
@112 **ויקרא לה נבח.** לה אינו מפיק ה''א. וראיתי ביסודו של רבי משה הדרשן לפי שלא נתקים לה שם זה, לפיכך הוא רפה, שמשמע מדרשו כמו לא. ותמהני מה ידרוש בשתי תיבות הדומות לה (רות ב, יד) ויאמר לה בעז, (זכריה ה, יא) לבנות לה בית:

@1 **אל ראשי המטות לבני ישראל.** אמר משה זה הדבור לנשיאי' בעבור בני ישראל או שיגידו זה המשפט לבני ישראל כי פעמים היה קורא משה הנשיאי' לבדם כאמרו בפרשת בהעלותך ואם באחת יתקעו ונועדו אליך הנשיאים וזה בחיי היה ראוי בהרבה מהדברים שהיה מדבר משה לבני ישראל כי לא היה ראוי שידבר דבריו לכל העדה גם לא יוכלו כלם לשמוע דבריו ואולם זכר זה בזה המקום לפי שמעצם משפט הנדרי' והשבועות היה שיהיה מסור לראשי המטות שהיו אנשים חכמים וידועים לפי מה שזכר בפרשת יתרו:
@2 **איש כי ידור נדר ליי'.** הנה עניין הנדר הוא שידור הרי בהמה זו עולה או חרס או מה שאפשר שידור אותו או יהיה זה כשידור אם יהיה כך אעשה כך כמו שמצאנו ביעקב שנדר נדר שאם יהיה מה ששאל מהש"י תהיה האבן ההיא בית אלהים ויתן לש"י מעשר מכל מה שיתן לו או שידור אם יהיה כך יהיה דבר כך אסור לו כמו שנדר ישראל אם נתון תתן את העם הזה בידי והחרמתי את עריהם והנה החרם הוא דבר הנדור כמו שנתבאר בפרשת בחקותי וכן אמר יפתח והעליתיו עולה ליי' כי העולה היא דבר הנדור והוא מה שאפשר שידוע אותו האדם והנה כבר נת ואשה כי תדור נדר ליי' ואסרה בארו דיני אלו הנדרים במה שקדם ויש עוד מין מהנדרים הם לאסור אסר על נפש הנודר כמו שאמר בזה המקום לאסור אסר על נפשו. ואשה כי תדור נדר ליי' ואסרה אסר. וזה הנדר אינו נדר שיהיה עצם הדבר נדור מצד עצמותו אבל הו נדור לאסרו על נפש הנודר לבד ויורה על זה שהבעל או האב מפירין נדרי האשה בעת שהוא ראוי שיהיו נדריה קיימים לפי שאין זה הנדר בעצם הדבר ולזה אמר לאסור אסר על נפשו והוא מבואר שזה הנדר לא יהיה אלא בדבר שיהיה בו נדר בעצמו' הדבר כי זה הוא מגדר הנדרים והמשל שכמו שאפשר לו לידור שתהיה בהמה זו עולה ותהיה אסורה לו ולכל אדם כן אפשר לו לומ' שהוא עליו כעולה ולזה תהיה אסורה לו לבד וזה ג"כ יהיה בשני פנים כמו העניין בנדרים האמתיים אם שלא יתלה נדרו בדבר אבל יאמר שהדבר ההוא יהיה עליו כעולה או כחרם ומה שידמה לזה אם שיאמר אם אעשה כך או יהיה כך הרי הדבר הפלו' אסור עלי כעולה או כחרם ומה שידמה לזה אם שיאמר אם אעשה או יהיה כך הרי הדבר הפלונית אסורה עלי ומה שידמה לה שיהיה נאסר בנדר וכמו שאי אפשר לאדם שידור שיהיה בהמה זו חזיר כי זה בלתי אפשר כן אי אפשר שיאסרה על נפשו כשיאמר הרי הוא עלי כחזיר וזה מבואר מאד כי זה הנדר הוא מאוחר מהנדר אשר יהיה בעצם הדבר והנה אמר ליי' כי הנדרים אשר יאסר בהם הדבר הם ליי' כמו העניין בקרבנות ובחרמות ובהקדשות:
@2 **או השבע שבועה.** הנה תהיה השבועה גם כן לאסור על נפשו הדבר בשבועה באחד משני מינים הנזכרים האחד הוא שיאמר הנני נשבע ביי' שלא אעשה כך או אעשה כך כי השבועה תחייבהו לקיים זה המאמר והשני הו' שיתלה השבועה בדבר אם אשה כך או יהיה כך אם עשיתי כך או היה כך הרי אני נשבע ביי' שלא אעשה כך או שאעשה כך:
@2 **לאסור אסר על נפשו.** ר"ל שלא יאסור הדבר כי אם על נפשו וזה יהיה בצד שספרנו. ולפי שאמ' לאסור אסר למדנו שאין הנדר הזה והשבועה הזאת להתיר לעצמו האסור אבל הוא לאסור המותר ולזה הוא מבואר שאם נשבע שלא לקיים את המצוה אין השבועה חלה כי אין זה אסר וגדר אבל הוא פרצת הגדר כאלו נשבע שלא ישב בסכה כי כמו זה אינו לאסור על אסר נפשו אבל הוא לסלק מנפשו חיובה ואולם בנדרים יקרה שיחולו על דבר מצוה והמשל שכבר יתכן שיאסור אדם על עצמו הנאת מצות סוכה עליו כקרבן והנה יחול זה הנדר לפי שאין מתנאי המצוה שיהנה האדם בהם כי כבר ידומה שיקיים המצוה ולא יהיה לו הנאה גופיית ממנה וזה יחולו הנדרים על דבר מצוה מה שאין כן בשבועות והנה זה ג"כ בנדרים כשהיו על דבר מצוה לא יהיה מקיומם עקירת המצוה כי אם במקרה ואמנם השבועות יהיה מקיומם עקירת המצוה בעצם וכמו שהו' מבואר שאם נשבע אדם שיעשה כך אחר נשבע שלא יעשהו 'שאין השבועה השנית חלה עליו כן אי אפשר שתחול השבועה שתהיה לעבור על שבועת סיני:
@2 **לא יחל דברו.** ר"ל שלא ישיב דבר חולין והרצון בזה שאף על פי שאנחנו רואים בהרבה מהדברים שהאדם עושה אותן קדש בעצמותן שהוא בעצמו יכול להשיבם חולין בפדותו אותם כמו שהתבאר בסוף פרשת בחקותי מעניין מעשר שני וההקדשות והיה זה ממה שיביא לחשוב שכל שכן שיוכל להשיב חולין דבריו בנדרים שאין הדבר בעצמותם קדש אבל הם אסורים לו לבד ולזה הצטרך לבאר שהוא מוזהר מלהשיב דברו חולין אבל יקיים ככל היוצא מפיו ועוד הצטרך לזה מצד אח' והוא שכבר ביאר שיש לבעל להפר נדרי אשו שהם לענות נפש מצד שענוי נפשה נוגע לו ויביא זה לחשוב שכל שכן שיוכל להפר נדרי עצמו ולזה אמרה ורה לא יחל דברו ונתחייב מזה שדברו אינו מחלל אבל דברים אחרים יוכל להשיב חולין כמו שראינו באב שמפר נדרי בתו והבעל נדרי אשתו ובכלל הנה ידמה שלזאת הסבה מסר משה זה המשפט לראשי המטות להורות שהראשים והם החכמי' מחללים דברי זולתם ר"ל שהם יוכלו להשיבם חולין כשרצה זה הנודר כי התורה מנעה ממנו שכאשר רצה לא יוכל להשיב דברו חולין כמו שהיה לו לעשות זה בקצת ההקדשות ומזה יתחייב שכאשר ירצה יוכלו אחרים להשיב דברו חולין אך האב והבעל לא יצטרך להם בחללם דברו שיהיה זה ברצונו ר"ל שיתחרט מהנדר ההוא או השבועה ההיא ולזה אמרו רז"ל שהחכם מתיר את הנדר כי הוא משיב את הדבר חולין ולזה יתבאר שהוא עוקר הנדר מעיקרו ולזה נכלל באמרו לא יחל את דברו שהוא מוזהר שלא יעבור על דבריו ויחללנו אבל יעשה ככל היוצר מפיו ויקיים אותו והוא אמו ככל היוצא מפיו יעשה והנה אמ' איש כי ידור נדר ליי' להוציא את הקטן שאינו איש ואינו בא להוצי' את האשה שהרי ביאר שנדריה קיימי' מה שלא הפרו אותם אביה או בעלה או נדר אלמנה או גרושה הוא קיים אע"פ שיש לה אב ולזה הוא מבואר שמי שהגיע לכלל איש ימי שהגיע לכלל אשה נדריהם קיימים:
@2 **ככל היוצא מפיו יעשה.** למדנו מזה שאע"פ שגמר בלבו צריך הוציא בשפתיו אבל דברים שבלב אינם דברים ומזה יתבאר עוד שאם הוציא בפיו מה שאינו בלבו אינו כלום כי ממגדר הדבור אשר הנדר אחד ממיניו שיוציא בו בפה מה שמכוין בלב ולפי שהדבור הוא מורה לפי ההסכמה הוא מבואר שאם היתה ההסכמה אצל המון מלות שיורו מהדבר אינם מורות עליו לפי טבע הלשון והוא הנודר אלו המלות בפיו להורות על מה שיורו עליו אצל ההמון הנה יהיה הנדר קיים כאלו אמר זה בלשון מורה בעצמותו לפי טבע הלשון על זה העניין כאלו תאמר שמצד פלגות ההמון יאמרו תמורת מלת שבועה שבואה או שבותה איך שהניחוהו כדומה לזה ואמ' הנשבע אלו המלות להורות בהם עניין שבועה הנה הוא נקשר בזה כאלו יאמ שבועה כי זה יקרא יוצא מפיו מצד הסכמת ההמון על זה ומצד כונת הנשבע שחשב להוציא בפיו מה שכוין בלבו בכמו אלו המלות:
@3 **ואשה כי תדור נדר ליי'.** להוציא את הקטנה וכבר ביארנו עניין זה הנדר והאסר בפסוק הקודם:
@3 **בבית אביה בנעוריה.** הנה הרצון באמרו בבית אביה שהוא ברשות אביה שאם היתה ברשו' בעל אין לאביה רשות בה כמו שאמר אחר זה ואם בית אישה נדר והוא מבואר מהעניין בעצמו שאין הכוונה באמרו בבית אביה כשתהיה תוך בית אביה כי אין רושם לבית בזה הענין אבל מה שיש לו רושם בו הוא השולטנות והממשלה שיש לאביה עליה כי זה ראוי שימנעה מלעשו' כל מה שתרצה וכן העניין בשולטנו' הבעל עליה בהיותה תחתיו והנה התנה שתהיה בנעוריה לפי שאח' עבור נעוריה יצאת מרשות אב והוא הזמן הנקרא בגרות והנה למדנו זה מזה המקום והנה ימי נעוריה הם לפי הוראת הגדר מהיותה בת שתים עשרה שנה ויום אחד עד ששה חדשים אחר זה קודם זה היא קטנה ואח' זה היא בוגרת לפי מה שהתבאר בשרשי' הכוללים ותכף שתהיה נערה תקרא אשה כי אז יצאתה מגדר הקטנות:
@4 **ושמע אביה את נדרה ואסרה אשר אסרה על נפשה.** הנה שמיעת האב את נדרה יהיה באחד משני פנים אם שישמע זה מפיה אם שיודיעוהו אחים כמו שאמ' יעקב לבניו הנה שמעתי כי יש שבר במצרים ולמדנו מאמרו את נדרה שצריך לשמוע נדרה או אסרה קודם שיפר:
@4 **והחריש לה אביה.** למדנו שאם שתק ולא הפר הנדר או האסר הנה הנדר או האסר קיים אך בתנאי שיהיה שתיקתו לה ר"ל שידע שבתו נדרה או אסרה אסר על נפשה והחריש לה ולא הפר נדרה ואסרה אך אם לא היה שתיקתו לה ר"ל ששמע ענין הנדר אבל לא ידע שבתו נדרה זה הנדר אע"פ שהחריש הנה הוא יכול להפר אחר זה כשידע שבתו היא שנדרה זה הנדר כי בתחלה לא החריש לה:
@5 **ואם הניא אביה אותה ביום שמעו.** הרצון בהנאה הפרה כמו שיתבא' מאמרו אחר זה יניא אותה והפר את נדרה ועניין ההפרה הוא בטול הנדר והאסר מאז ולהבא מאמרו אח' זה יניא אותה ותופר וידעו כן עניי הצאן השומרי' את דברי. ובכלל הנה הוא מבואר מצד הוראת הנדר מלת ההפרה והנה למדנו מזה שביום שמעו לבד יוכל להפר לא אחר זה ואע"פ שלא שמע הנדר אלא אחר כמה ימים יוכל להפר ביום שמעו והכונה באמרו ביום שמעו מעת לעת כמו שאמר אחר זה מיום אל יום אם הפר אע"פ שאין בתו יודעת הנה אין נדריה ואסריה קיימים:
@5 **ויי' יסלח לה כי הניא אביה אותה.** לפי שאין הסליחה אלא במקום חטא וידענו שאין חטא לבת אם עברה על דברי נדריה ואסריה אחר שהפר אותה האב לפי שהם מבוטלים וכאלו אינם הנה יחוייב שהרצון יהיה בזה שאם היה שלא תדע הבת בזו ההפרה ועשה כנגד נדרה ואסרה ונתכוונה לעבור על דרה ואסרה הנה יי' יסלח לה על זאת המחשבה אחר שכר הופר נדרה ואסרה וראוי שתדע שההקם יהיה באחד משני פנים אם שיחריש ביום שמעו ואחר זה הוקם מעצמו והנה זה ההקם אין לו היתר כי כבר בא מעצמו והמון השני הוא שיאמר שהוא מקיים את הנדר או את האסר תוך הזמן שהיה לו להפר אותו לפי שזה העניין שהוציא מפיו הוא כמו נדר הנה נשאל עליו לחכם ויתירהו מההקם ואחר זה יוכל להפר נדרי בתו כיון שהוא עדין ביום שמעו ואולם אם הפר אינו נשאל על ההפר כי אין זה נדר ולא מתיחס לנדר אבל הוא בטול נדר והנה ההפרה יתכן שתהיה ע"י שליח כי שלוחו של אדם כמותו בכמו אלו הדברים אשר יסבלו שליחות וזה מבואר מצד הוראת הגדר:
@6 **ואם היו תהיה לאיש ונדריה עליה.** הוא מבואר מצד הוראת הגדר שהאשה תהיה לאיש מעת שנתארסה והיא גם כן אז בבית אביה כמו שנתבאר בפרש' כי תצא למלחמה שאביה זוכה בקנס שנותן הבעל בהוציאו שם רע עליה למדנו מזה שלא יצאת מרשות אב עד שנשאת ולזה הוא מבואר שאי זה שיהיה מהם יוכל להפר אז את נדרה בעודה נערה ואולם אחר זה לא יוכל להפר נדרה זולת הבעל והנה הרצון באמרו ונדריה עליה שלא נתחדש בהם דבר מצד האב ר"ל שלא נתקיימו ולא הופרו כי אז הם נדריה ואסריה אשר אסרה על נפשה לא אחר שהקומו כי אז אסרוהו אחרים על נפשה וכ"ש שלא יהיה זה אחר שהורו כי אז אינם עליה והנה למדנו מזה שאפי' הדברי' שדרה קודם שנתארסה מפר הבעל ביום שמעו כיון שהחריש לה אביה מיום אל יום באופן שיהיו מקויימים כ"ש בנדרים שנדרה אחר שנתארסה:
@6 **מבטא שפתיה.** ר"ל שבועה כמו שאמר בשבועה לבטא בשפתים בפרשת ויקרא ולזה אמר אחר זה כל נדר וכל שבועת אסר להורות שמה שאמ' ואסרה אשר אסרה על נפשה ומבטא שפיה אשר אסרה על נפשה הנה הרצון בו שבועה והוצרך לבאר זה כי אולי יחשוב חושב כי בנדר לבד נתנה התורה זה הכח לאב ולבעל לא בשבועה כי היא יותר חמורה והנה הנמשך לזה מבואר ממה שקדם עד אמו ונדר אלמנה וגרושה וראוי שתדע שהרצון בזה באלמנה וגרושה שנתאלמנה או שנתגרשה מן הנישואין ועדיי היא נערה ולזה הוצרך לומר כל אשר אסרה על נפשה יקום עליה כי היה לחושב שיחשב שכיון שהיא נערה עדין תשוב לרשו' האב אע"פ שנתאלמנה או נתגרשה עדיין אני קורא בה בנעוריה בית אביה ולזה הוצרכה התורה לבאר זה ולמדתנו בזה שכיון שיצאת מרשות אב הנה אינה שבה תחת רשותו במיתת הבעל או בגט אבל היא קונה את עצמה באלו הדרכים מהבעל ואולם אם נתאלמנה או נתגרשה מן האירוסין והיא נערה הנה הוא מבואר שעדיין לא יצאתה מרשות האב כי גם בהיותה תחת רשות ארוסה היא עדיין תחת רשות האב להפר נדריה ולקיימם כמו שביארנו אף כי בצאתה מרשות ארוסה וזה ממה שאינו ריך ביאור למעיין בזה הספר וראוי שתדע שהפרת הנדר או השבועה לא יתכן היותו קודם היותם חלים כי אין זה הפר וזה מבואר בעצמו וכן העניין בהיתר החכם הנדר או השבועה כי לא יתכן לחלל הדבר שלא נתקדש:
@10 **ואם בית אישה נדרה.** ר"ל אחר שנשאת כי אז היא בבית אישה ושאר מה שנמשך לזה מבוא' ממה שקדם עד אמרו כל נדר וכל שבועת אסר לענות נפש והנה הסבה בזה לפי שהנדרים שיש בהם ענוי נפש הנה הבעל נוגע בדבר מפני היותר קניין מקנייניו והיא פוחתת בזה קניין הבעל וטוב לבעל שתהיה אשתו בזולת ענוי נפש כי בצרתה לו צר ומזה יתבא' שכ"ש שיש לבעל להפר נדרים שבינו לבינה כי היא יותר נוגעת בדבר ההא ממה שהוא נוגע בדברים שיש בהם ענוי נפש כאלו תאמר שנדרה שלא תרחץ מטומאתה או שאסרה על נפשה הנאת משכב בעלה וזה מבואר מאד:
@15 **ואם הפר יפר אותם אחרי שמעו ונשא את עונה.** ר"ל אחר יום שמעו יכריח אותה לבטל נדרה או שיאמר לה שהוא מיפר נדריה ויביא אותה לחשב שנדריה מופרין הנה החטא ההוא הוא עליו:
@16 **אלה החקים אשר צוה יי' את משה.** שב עתה לזכור בכללות מה שכללה אותו זאת הפרשה.
@18 **נקום נקמת בני ישראל מאת המדינים.** בעבור שע"י משה תשלם זאת הנקמה באופן יותר שלם רצה הש' ית' שתעשה ע"י עם שכבר היה ראוי למהר זאת הנקמה בעבור הסבה שזכרה בפרש' פנחס והנה רצה הש"י להראו' עוצם השגחתו בישראל שלא ישלחו לצבא כי אם י"ב אלף אלף לכל מטה מהמטות זולת שבט לוי שלא היו יוצאי' לצבא כי לא היה להם חלק בארץ:
@22 **אותם ואת פנחס.** ר"ל שכבר שלח אותם משה ואת פינחס:
@22 **וכלי הקדש וחצוצרות התרועה בידו.** אחשוב שוי"ו תיבת וחצוצרו' היא כפה רפה בלשון ישמעאל שיקרה בה שתהיה ללא עניין כמו ואיה וענה ורכב וסוס. והנה הרצון בו שכלי הקדש שהם חצוצרות התרועה היו ברשותו כי בהם יתקעו במלחמות כמו שנזכר בפרשת בהעלותך.
@24 והנה זכר שהם הרגו כל זכר במדי' והרגו' עם זה חמשה **מלכי מדין** ובלעם עמה' להורות שכבר היה שקול עניין הריגתו לדבר הריגת המלכים וזכר שכבר היו כל נקבה והטף כלו ושבו אותם וגזזו להם הבהמה והמקנה וכל חילם:
@26 **ואת כל טירותם.** הם הערי' הבצורות המוקפות חומה ויקחו כל השלל ואת כל המלקוח וגו' העיד הכתוב שלא כבש אחד מהם דב מהשלל ומהמלקוח לעצמו אבל הביאו הכל למשה ולאלעזר הכהן ואל כל עדת בני ישראל:
@30 **ויקצוף משה על פקודי החיל.** לא כעס אלא על הגדולים המנהיגי' כי אין לאחרים אשם לפי שלא יוכלו לעשו' כי אם מה שיצוום מנהיגיהם והנה צוה משה שיהרגו כל זכר בטף כדי שלא ישאר בהם זכרון ושיהרגו הנקבות היודעות משכב זכר והנה ידעו מי הנקבות שלא ידעו משכב זכר מפי הגבור' או היה להם סימן בזה להושיבם על חבית יין והבעולה היה ריחה נודף כמו שאמרו רבותינו זכרונם לברכה והנה אחשוב שהיודעות איש למשכב זכר הן הנבעלות כדרכן כי כן דרך משכב זכר. או יהיה הרצון באמרו כל אשה יודעת איש למשכב זכר כל הראויה ליבעל אף על פי שלא נבעלה כמו שאמרו רבותינו זכרונם לברכה בסיפרי:
@35 **ואתם חנו מחוץ למחנה שבעת ימים וגו'.** למד הכתוב על הרוגי מדין שמטמאין כמתי ישראל:
@35 **אתם ושביכם.** לפי שהשבי נכנס בכלל ישראל עשה דינו להטמא בהרוגי מדין כדין ישראל:
@36 **וכל בגד וכל כלי וגומ'.** רוצה לומר במי נדה להזות עליהם שלישי ושביעי מפני התטמאם באהל לא יטמאו באל אלא כלים או אדם לא קש ותבן כמו שביארנו בפרשת פרה והנה מעשה עזים הוא בהכרח דבר אינו בגד ולא כלי עור ולזה הוא מבואר שאינו דבר נעשה מנוצה של עזי' ולא מהשער ואינו גם כן נאד נעשה מהעור כי הוא כלי עור אך הוא כלי נעשה מקרן העזים והוא אם כלי שיש בו בית קבול כמו שיחתכו הציירים חלק מהקרן ובבית קבול שבו ישימו הצבע או יעשו ממנו כלים פשוטים כמו המסרק ולוחות העששית ומזה המקום למדנו שכן הדין בכלים הנעשים מהטלפים ומעצמות העזים ומה שידמה להם:
@38 **אך את הזהב.** למד על כל כלי מתכת שמטמאין כמת והוא מבואר שבכלים הכתוב מדבר שהרי זכר אחר כן צד תשמישן ולמה עוד עליהם שצריכין הכשר מפני מה שבלעו מהמזונות האסורים לנו וביאר שכבר יפלוטו מה שבלעו בדמיון שבלעוהו והמשל שהשפוד אשר יבא באש כאשר יצלו בו הנה יעבירוהו באש לפלו' מה שבלע ואם יבא במים כמו הענין ביורות יעביריהו במים רוצה לומר במים הרוחתין כמו שאמר בחטא ואם בכלי נחשת בושלה ומורק ושוטף במים ומה שזכר אך במי נדה יתחטא ר"ל אחר שטבל הכלי:
@40 **וכבסתם בגדיכם ביום השמיני וטהרתם.** ילמד בזה שטעונים כבוס בגדים ושהבגדים גם כן טמאים טומאת שבעה מפני שנטמא יחד באהל או מפני היותם מחוברים למחובר למת:
@42 **שא את ראש מלקוח השבי.** כמו שבמעשר ראשון יקחו הכהנים כמו עשירית חלק הלויים כן היה זה הענין בכמו זה היחס בקירוב כי עשירית חלק אחד מן החמשים הוא חלק אחד מחמש מאות ולזה לקחו הלויים חלק אחד מן החמשים מחצי המלקוח ואלעזר לקח חלק אחד מחמש מאות בו והנה היה כחלק היורד אל המלחמה כחלק היושב על הכלים במלקוח וכבזה ולא חלקו הכל בין כל ישראל לפי שהוא אפשר שזכות הבאים לצבא שהיו כלם אנשים כשרים כמו שהעיד אמו ויקחו את כל השלל היה סבה אל שיהיו נעזרים יותר בשם יתעל ממה שיהיו נעזרים בו אם היו באים כלם לצבא כי בחטא אחד מהם יכשלו כלם כמו שזכרנו בפרשת קרח שלא היה השלל כלו לאנשי הצבא לפי שמצד ההשגחה הדבקה לכלל ישראל נעזרו גם כן בזה הפעל ולזה רצה הש' יתעלה שיהיה כחלק היורד אל המלחמה כחלק היושב על הכלים ואפשר שמזה המקום נתיישר דוד לשום זה הענין לחק כמו שנזכר בספר שמואל. והנה האריך לספר מספר כל זה המלקוח ושכבר נתנו ממנו החלק הראוי לכהנים וללויים כמשפט התורה להאריך בכמו אלו הדברים כמו שבארנו הסבה בפרשת נשא עם שמזה המספר תועלת רב לדעת עוצם ההצלחה בזאת המלחמה עד שבמתי מעט נצחו עם רב כזה היו בטירותם ובעריהם עד שכבר היה מספר חטף מהנשי' אשר לא ידעו משכב זכר שנים ושלשים אלף ולא נפקד איש מאנשי הצבא. והנה ספר שראשי אנשי הצבא בראותם עוצם השגחת הש' יתעלה בהם הסכימו לתת כבוד לשם יתעלה מהונם אשר הציל את נפשותם מהמות ולזה נתנו מכלי הזהב השלמים לש"י שרי האלפים ושרי המאות זה השיעור שזכרה אותו התורה והורה עליו שהכלי' ההם היו שלמים מה שאמר בהם כל כלי מעשה ר"ל שהיו ראויים לשמש למה שנעשו לו והנה הושמו הכלים ההם באהל מועד לזכרון לפני יי' למען ידעו הדורות הבאים עוצם ההצלחה שהגיע בזאת מלחמה שלא היה כמוה בשום מלחמה שסופרה בכתוב.
@71 ואחר זה ספר כי מפני שהיה מקנה לבני גד לבני ראובן התעוררו לשאול ממשה הארץ אשר הכה הש"י לפני עדת בני ישראל כי היא ארץ מקנה לזה בחרו שתהיה הארץ ההיא לנחלתם ולא יעבירם את הירדן.
@76 ולפי שידע שכונתם היתה שלא יעברו את הירדן להלחם עם הגוים אשר שם כעס עליהם מאד ואמר להם ששאלתם זאת תניא לב העם מעבור הירדן וכבר היה ראוי להם להשמר מזה כי מפני תנואת המרגלים נתאחרו במדבר עד תום כל הדור ההוא ואם עתה יניאו לב העם יתאחרו עוד במדבר וישחתו כי כמה מקרים קשים קרו להם במדבר בקש הש' יתעלה לכלותם עליהם עם היות משה קיים ואף כי אחרי מותו עם שלא היה שם נביא זולת משה יהיה ראוי להעשות על ידו כמו זה המופת הנפלא לכלכל כל העם הזה במדבר:
@86 והנה ענו בני גד ובני ראובן כי הם יקחו עצה שלא יניאו כזה לב העם וזה שהם יבנו במהירות גדרות צאן למקניהם וערים לטפיהם וישב טפם בערו המבצר מפני יושבי הארץ ובעבור שלא יניא לב העם יחלצו במהירות לצבא בלי שום עצלה לבאר שהן בוטחים בהש' יתעלה שינצחו הגוים אשר שם ולא ישובו אל בתיהם עד התנחל בני ישראל איש נחלתו:
@90 והסכים משה לדבריהם אם יעשו הדבר הזה והודיעם עוצם חטאם אם לא יקיימו היוצא מפיהם עד הורישו את אויביו מפניו ונכבשה הארץ לפני יי' הנה התנה משה אלו ב' התנאים כי אפשר שיוריש הש' יתעלה את אויביו מפניו והם באים לחלחם עם ישראל ועדין לא תהיה הארץ נכבשת לפני השם עד שלכדו בני ישראל הערים ההם כמו שמצאנו במלחמות יהושע שהוצרכו אחר זה ללכת אל הערים שהיו מהמלכים שהמיתו במלחמה ללכדן והנה היתה כונת משה שתהיה הארץ נכבשת לפני יי' קודם שישובו בני גד ובני ראובן לנחלתם כי לא יהיה מהיושר שיקחו בני גד ובני ראובן לנחלה הארץ נכבשת לישראל ויניחו לישראל הארץ הבלתי נכבשת להם:
@98 ואמר משה לאלעזר הכהן וליהושע בן נון ולראשי המטות שאם יקיימו בני גד ובני ראובן התנאי הנזכר תהיה להם הארץ ששאלו לאחזה ר"ל שבה ינתן להם חלקם הראוי מכלל ארץ ישראל ואם לא יקיימו זה התנאי לא תהיה להם הארץ הזאת לאחוזה אבל יאחזו בתוך בני ישראל בארץ כנען על פי הגורל ומזה המקום למדנו רוב דיני התנאי השלם איך יהיה המאמר בו שיועל התנאי והנה אחר זה מפני שהתבאר למשה מפי הגבורה שאין ראוי שתגיע כל הארץ אשר מעבר הירדן מזרחה לבני גד ולבני ראובן שם בזאת הנחלה ג"כ חצי שבט מנשה וזכר אחר זה שכבר בנו בני גד ובני ראובן ערי מבצר וגדרות צאן כמו שהתנה למשה מסבות שם ידמה ששנו השמות שהיו להן תחלה כטעם ויסב את שמו צדקיה ותהיה על דרך משל העיר שקראוה חשבון אינה העיר שנקראת כך תחלה. ואפשר שהרצון בו שהסבו להם השמות הראשונים שהיו להם:
@109 **וילכו בני מכיר בן מנשה גלעדה וילכדוה.** רוצ' לומ' שלכדו קצת עיר הגלעד וידמה שזה היה בעת מלחמות עוג כי כבר כתוב שם ויירשו את ארצו וכן היה אז כבישת יאיר את הוותיהם וכבישת נובח קנת ובנותיה ולזה הסכים משה מפי הגבורה שתחיינה אלו לאשר כבשום בחלק נחלתם. והנה זכר זה הכתו' במכיר בן מנשה קצר מפני זה הבאור בנבח כי סמך על באור מה שנזכר מזה למכיר בן מנשה ולולי היות אלו לנחלה ללוכדיהם לא קרא יאיר לאלו המקומות חוות יאיר ולא קרא נבח המקום נבח בשמו והוא אפשר גם כן אחר שהגיעה להן נחלתן בהר הגלעד מעבר לירדן מזרחה כבשו אלו המקומת סביב נחלתם כמו שמצאנו בספור יהושע שאמר יהושע לבני יוסף אם עם רב אתה עלה לך היערה בראת לך שם בארץ הפריזי והרפאים כי אין לך הר אפרים למדנו מזה שמה שיכבשו סביב נחלתם הוא שלהם וכל שכן בזה המקום שכבר הגיע בכללות מה שמעבר הירדן מזרחה לשני השבטים וחצי השבט והנה בכאן נשלם מה שצריך לבאר בזאת הפרשה.

@1 וידבר משה אל ראשי המטות לבני ישראל לאמר עד נקום נקמת בני ישראל מאת המדיני'.
@1 ואולם התועלות המגיעות מזאת הפרשה הם שנים:
@1 **התועלת** הא' הוא במצות והוא שלא יעבור הנודר נדרי אסר או הנשבע שבועת אסר על דברו אבל יקיים ככל היוצא מפיו ויש בזה שתי מצות האחת מצות לא תעשה והשנית מצות עשה והנה התועלת באלו המצות מבואר כי אם היה מותר לאדם לחלל דברו היה זה מביא להקל באמונת הש' יתעלה כמו שזכרנו בעניין טעם אזהרה שבועת שוא עם שבזה תועלת מהדברים המדיניים לקיים כל דבר בכמו אלו האסרים ובו עוד תועלת כי בהם יזדרז האדם את עצמו בהרבה מהפעולות הטובות ולו היה לאדם להתיר נדרי עצמו יסור התועלת מאלו הדברים:
@1 **התועלת** הב' הוא במצות והוא לדון בדיני הפרת נדרים בין איש לאשתו בין אב לבתו בנעוריה בית אביה והנה התוע' בזאת המצוה מבואר כי לולי זה תסור הממשלה מהאב על בתו במה שיקוה או מהאיש על אשתו עם שיהיה זה סבה להיות קטטה ביניהם תמיד כי הנשים מצד היות דעתן קלה עליהם מובנות מאד לאלו הנדרים והשבועות והנה נתנה התורה פנאי לזאת ההפרה מעת לעת כדי שיתישב בזה יותר האב או הבעל ואם יקרה שבסבת כעס לא יפר תכף הנה יסור כעסו ויתיישב דעתו תוך יום שלם לפי הנהוג מהאנשים על הרוב:
@109 ואלו התועלות המגיעים ממנה הם י"ב:
@109 **התועלת** הראשון הוא להודיע עוצם זריזות משה לעשות מצות השם יתעלה שאף על פי שידע שאחר זאת המלחמה יאסף על עמיו לא נתעצל בה אך מהר לנקום זאת הנקמה לפי מה שאפשר:
@109 **התועלת** השני הוא להודיע שהשלמים אינם חרדים מהמות כי אינם בוחרים מאד באלו החיים הגופיים כי היותר טוב להם אחר שקנו מן המושכלות שימותו כדי שיתענגו תמיד בהשגת כל המושכלות אשר קנו אותן יחד כי אז לא ימנע החמר זאת ההשגה כמו שנתבאר זה במקומותיו. ולזה לא תמצא שחרד משה מהמות בזה המקום ולא במקום אחר אך בקש משה מהש' ית' שיפקוד איש על עדה אשר ישתדל בהנהגתם כי כונתו כלה היתה אל שימשך מטוב בסבתו מה שאפשר לו.
@109 **התועלת** הג' הוא להודיע מה שהיה מעצם ההשגחה בזאת המלחמה כי במתי מעט באו על עם רב מאד היו בחצריהן ובטירותם והרגו אותם בכללם ולא נפקד איש מבני הצבא והיו הנהרגים באופן מהרבוי עד שהיה הטף בנשים אשר לא ידעו משכב זכר שלשים ושנים אלף והיה עוד מעוצם ההצלחה בזאת המלחמה שכבר המיתו בה בלעם בן בעור כי אם היה נשאר אולי ישתדל להזיק להם:
@109 **התועלת** הד' הוא לפרסם הפלגת אהבת ה' ית' לישראל כי בהתפרסם לפניו שעם מדין ידעו ישראל בתכלית מה שאפשר להם השתדל בסבות הנאותות לכלותם בעת היות ישראל נעזרים בהשגחה אלהית הלא תראה איך היה מנהג הנשארים בהן עם ישראל בספר שופטים עם שכבר הרעו לישראל יותר משאר האמות אשר משלו עליהם ולזאת הסבה היתה המצוה להרוג בהם כל זכר עם שהשארת הזכרים בטף אולי יהיה להם למכשול בעניין ירושת הארץ כי בהתאחדם עם כלל ישראל יזוקו ישראל בחטא אלו אשר היו מוכנים לו מצד טבע הצור אשר חוצבו ממנו ומצד המנהג שגדלו בו והנה לזאת הסבה ג"כ צוה הש"י למחו' את זכר עמלק הלא תראה כי מהמעט שנשא בהם יא צפע דמה לכלות עם ה' והוא המן בן המדת האגגי ולזאת הסבה צוה להרוג נקבות מדין אשר ידוע ממשכב זכר פן יכשלו ישראל ויסירום מאחרי השם יתעלה:
@109 **התועלת** הה' הוא לפרסם יושר אנשי הצבא שלא היה בהם איש שהחביא דבר מהשלל אך הביאו כלו לפני משה והנשיאים וכל העדה כאלו העירנו בזה כי יושר לבבם היה כלי אל שהגיע להם זאת ההצלחה העצומה בזאת המלחמה:
@109 **התועלת** הששי הוא במדות והוא להודיע כי המתחיל במעשה אחד טוב ראוי שיזכה בהשלמת המעשה ההוא עד תכליתו ולזה ספר כי פינחס היה הראש בזאת המלחמה כי הוא התחיל לתת נקמת השם במדיין במה שהרג כזבי בת צור אשר באה להכשיל ישראל בזנותה והיה בזה גם כן סבה אל שנעצרה המגפה מעם השם ולזה רצה הש"י שיזכה להיות הוא הראש בזאת המלחמה אשר כוון לתת נקמת יי' במדין ולהציל ישראל מהיזקם במה שעתיד לפי מה שאפשר:
@109 **התועלת** הז' הוא לפרסם כי אין כח בקסם שיגיע ההודעה במה שיתחייב מההשגחה האלהית במה שעתיד לאשר תדבק בהן ולזה זכר שכבר חרגו בלעם בן בעו' עם היותו קוסם לא קדמה לו הידיעה בזה לקחת עצה להציל עצמו בשיצא מהמקומות ההם שהשחיתום ישראל:
@109 **התועלת** הח' הוא לפרסם שכבר השיב הש' יתע' גמולו לבלעם על זדון לבו במה שנתן עצה להכשיל ישראל בעריות ובע"ז כדי שיחר אף השם יתעלה בהם ויכלם:
@109 **התועלת** הט' הוא להודיע שמי שהגיע לו טוב מהשם יתעלה ראוי שיכירהו ויודה עליו לשם יתעלה כי בזה מהתועלת מה שלא יעלם ולזה ספר ששרי האלפים והמאות התנדבו לשם יתעלה כלי זהב רבים על כל הטובות אשר גמלם שלא נפקד איש מאנשי המלחמה ולזאת הסבה בעינה הביאם משה אל אהל מועד להשאיר זכר זה המופת הנפלא ולזה ג"כ צוה הש"י שיקחו תרומת השם מהשלל לתת לכהנים וללוים להעיר שה הטוב הנפלא הגיע להם מהש"י לא מצד כחם ועוצם ידם:
@109 **התועלת** הי' הוא להודיע שראוי לכל אדם להתרחק מעשות מה שאולי יהיה סבה להחטיא זולתו ולזה כעם משה על בני גד ובני ראובן בשאלם להם לנחלה הארץ אשר בעבר הירדן מזרחה מצד מה ששאלתם זו אולי תהיה להניא לב ישראל מעבור הירדן כי אולי יחשבו של זאת הסבה בחרו להם בני גד ובני ראובן זה לשערם שלא יוכלו ישראל להוריש הגוי' אשר שם ולזאת הסבה תמצא שכאשר הסכימו ללכת שם לצבא שלא היה אז לירוא מהנאת לב העם בשאלתם כי הם רואים צאתם עמם לצבא ולולי בטחם בשם יתעלה שיכניע הגוים ההם לפניהם לא נכנסו בזאת המלחמה:
@109 **התועלת** הי"א הוא במסות והוא להודיע שראוי לכל אדם להרחיב הדברים בעסק שיהיה לו עם זולתו באופן שלא יהיה אפשר שיקרה בו שום מרמה ותחבולה ולזה תמצא שדקדק משה רבינו עליו השלום בזה התנאי שהתנה עם בני גד ובני ראובן והרחי' הדברי' בו בצד שלא יתכן בו שום מרמה:
@109 **התועלת** השתים עשרה הוא במדות והוא שאין ראוי לאדם שיפותה בעבור תועלות פרטיות לבחר דבר על דבר אם לא אחד התישבות רב הלא תראה כי מפני היות מקנה רב לבני גד ולבני ראובן נפתו לבחור הארץ אשר בעבר הירדן מזרחה להיות המקום מקום מקנה והנה השיגם מזה החרטה אחר שנכבשה הארץ כי ראו שאולי זה יהיה סבה אל שיסורו בניהם מאחרי השם יתעלה והוצרכו מפני זה לבנות המזבח ההוא שנזכר בספר יהושע עם שהם היו יותר מוכנים לנפול ביד מצירי לישראל מזולתם ולזה תמצא שהראשונים שהגלה מלך אשור היו אלו השבטים עם שהמואבים היו לה תמיד לקוץ מכאיב מצד האר' הזאת שנחלו ישר' מהם על יד סיחון כמו שתראה מדברי יפתח הגלעדי:
